for seed in range(3):
    torch.manual_seed(seed)
    for affine in ['default','learned_random']:
        if affine=='default':m.ln.weight.fill_(1);m.ln.bias.zero_()
        else:m.ln.weight.normal_();m.ln.bias.normal_()
