    x.mul_(.8);m.ln.weight.mul_(.9);m.ln.bias.add_(.01);g.replay();case['graph_mutation']=check(m(x),out)
    r['timing'][aff]=case;print(aff,{n:round(v['median_ms'],6) for n,v in case['graph']['stats'].items()},'mutation',case['graph_mutation'],flush=True)
    del x,ts,funcs,g,out;gc.collect();torch.cuda.empty_cache()
for shape in [(8,32,128,256),(4096,1,1,1024),(3,64,17,19)]:
