import gc,json,torch
import wide_layernorm as wl
from norm_baselines import ROOT,load
from experiment_fusion import bench,check
torch.set_grad_enabled(False)
mod=load(40);report={'scope':'official L1/40 default shape, ordinary-input candidate with known offset failure','shape':[16,64,256,256],'config':wl.CONFIG,'checks':[],'timing':{}}
m=mod.Model(*mod.get_init_inputs()).cuda().eval()
def split(x):
    v,u=torch.var_mean(x,dim=(1,2,3),unbiased=False,keepdim=True)
    return ((x-u)*torch.rsqrt(v+m.ln.eps))*m.ln.weight+m.ln.bias
class Split(torch.nn.Module):
    def __init__(self):super().__init__();self.model=m
    def forward(self,x):
        v,u=torch.var_mean(x,dim=(1,2,3),unbiased=False,keepdim=True)
        return ((x-u)*torch.rsqrt(v+self.model.ln.eps))*self.model.ln.weight+self.model.ln.bias
for seed in range(3):
    torch.manual_seed(seed)
    for affine in ['default','learned_random']:
        if affine=='default':m.ln.weight.fill_(1);m.ln.bias.zero_()
        else:m.ln.weight.normal_();m.ln.bias.normal_()
        for dist in ['uniform','normal','scaled_100','offset_1000']:
            x=mod.get_inputs()[0].cuda() if dist=='uniform' else torch.randn(16,64,256,256,device='cuda')
            if dist=='scaled_100':x*=100
            elif dist=='offset_1000':x+=1000
            ref=m(x)
            for name,fn in [('split',lambda:split(x)),('flat',lambda:wl.forward(x,m.ln,False)),('interleaved',lambda:wl.forward(x,m.ln,True))]:
